package io.github.samlinb.openbone.core;

import java.util.*;
import org.junit.jupiter.api.*;
import io.github.samlinb.openbone.core.model.*;
import io.github.samlinb.openbone.core.animation.*;
import io.github.samlinb.openbone.core.math.*;
import io.github.samlinb.openbone.application.*;
import io.github.samlinb.openbone.io.*;
import io.github.samlinb.openbone.viewport.*;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.samlinb.openbone.TestData.id;

public class P8ModelTest {
    public static DocumentSnapshot sample(){
        var root=new Bone(id(1),"root",null,Transform.IDENTITY,20);var slots=List.of(new Slot(id(10),"back",id(1),id(20)),new Slot(id(11),"middle",id(1),id(21)),new Slot(id(12),"front",id(1),id(22),Slot.Blend.ADDITIVE));
        List<Attachment> attachments=List.of(new RegionAttachment(id(20),"image",id(10),"page.png",Transform.IDENTITY,20,10),new RegionAttachment(id(21),"image",id(11),"page.png",Transform.IDENTITY,20,10),new RegionAttachment(id(22),"image",id(12),"page.png",Transform.IDENTITY,20,10),new RegionAttachment(id(23),"image",id(10),"other.png",new Transform(30,0,0,1,1),20,10),new RegionAttachment(id(24),"alternate",id(10),"page.png",Transform.IDENTITY,10,10));
        var skins=List.of(new Skin("default",Map.of(id(10),Map.of("image",id(20),"alternate",id(24)),id(11),Map.of("image",id(21)),id(12),Map.of("image",id(22)))),new Skin("red",Map.of(id(10),Map.of("image",id(23)))),new Skin("empty",Map.of()));
        var event=new EventDefinition(id(40),"hit",7,.25,"默认","",1,0);var d=new DocumentSnapshot(List.of(root),slots,attachments,List.of(new AnimationClip(id(30),"walk",List.of())),List.of(),new Resources(skins,"default",List.of(event),Map.of()));
        d=ExtendedEdits.attachment(d,id(30),id(10),0,"image");d=ExtendedEdits.attachment(d,id(30),id(10),.5,null);d=ExtendedEdits.attachment(d,id(30),id(10),1,"alternate");
        d=ExtendedEdits.drawOrder(d,id(30),.5,List.of(id(12),id(11),id(10)));d=ExtendedEdits.drawOrder(d,id(30),1,List.of(id(10),id(11),id(12)));
        for(double t:new double[]{0,.5,1})d=ExtendedEdits.event(d,id(30),new DiscreteTracks.EventKey(EntityId.create(),t,id(40),(int)(t*10),t,"键"+t,1,0));return d;
    }
    @Test void skinIdentityFallbackMissingAndSetupIsNotAnimation(){var d=sample();assertEquals(id(20),d.resolveAttachment(id(10),"image"));var red=ExtendedEdits.skin(d,"red");assertEquals(id(23),red.resolveAttachment(id(10),"image"));assertEquals(id(21),red.resolveAttachment(id(11),"image"));assertNull(red.resolveAttachment(id(10),"missing"));assertNull(red.resolveAttachment(id(10),null));assertEquals(id(20),d.slots().get(0).activeAttachmentId());assertEquals(30,red.evaluateWorld().regions().get(id(23)).matrix().tx(),1e-9);assertThrows(IllegalArgumentException.class,()->ExtendedEdits.skin(d,"unknown"));}
    @Test void discreteBoundariesAndLoop(){var d=sample();for(double t:new double[]{0,Math.nextDown(.5),Math.nextUp(0.0)})assertEquals(id(20),d.resolvedSlots(id(30),t,false).get(0).activeAttachmentId());for(double t:new double[]{.5,Math.nextUp(.5),Math.nextDown(1.0)})assertNull(d.resolvedSlots(id(30),t,false).get(2).activeAttachmentId());assertEquals(id(24),d.resolvedSlots(id(30),1,false).get(0).activeAttachmentId());assertEquals(id(20),d.resolvedSlots(id(30),1,true).get(0).activeAttachmentId());assertEquals(id(12),d.resolvedSlots(id(30),.5,false).get(0).id());assertEquals(id(10),d.resolvedSlots(id(30),1,true).get(0).id());}
    @Test void geometryAndPickerShareOrder(){var d=sample();var p=d.evaluateAnimatedWorld(id(30),.5,false);var draws=VisibleGeometry.evaluate(d,p);assertEquals(List.of(id(22),id(21)),draws.stream().map(VisibleGeometry.Draw::attachmentId).toList());assertEquals(Slot.Blend.ADDITIVE,draws.get(0).blend());}
    @Test void eventsInitialEndMultiLoopAndPauseIntervals(){var clip=sample().animation(id(30));var initial=EventSampler.between(clip,0,0,true,true);assertEquals(1,initial.size());assertEquals(0,initial.get(0).key().time());assertEquals(0,EventSampler.between(clip,0,0,true,false).size());var all=EventSampler.between(clip,0,3,true,true);assertEquals(10,all.size());assertEquals(List.of(0.,.5,1.,1.,1.5,2.,2.,2.5,3.,3.),all.stream().map(EventSampler.Fired::absoluteTime).toList());assertEquals(1,all.get(2).key().time());assertEquals(0,all.get(3).key().time());assertEquals(2,EventSampler.between(clip,0,1,false,false).size());var split=new ArrayList<EventSampler.Fired>();split.addAll(EventSampler.between(clip,0,.5,true,true));split.addAll(EventSampler.between(clip,.5,3,true,false));assertEquals(all,split);assertThrows(IllegalArgumentException.class,()->EventSampler.between(clip,1,0,true,false));assertThrows(IllegalArgumentException.class,()->EventSampler.between(clip,0,100001,true,false));}
    @Test void duplicateEventsAtSameTimeKeepOrder(){var d=sample();d=ExtendedEdits.event(d,id(30),new DiscreteTracks.EventKey(id(51),.5,id(40),55,0,"second",1,0));var fired=EventSampler.between(d.animation(id(30)),0,.5,false,false);assertEquals(2,fired.size());assertEquals(55,fired.get(1).key().intValue());}
    @Test void eventAbsoluteClockDoesNotAccumulateLoopError(){var clock=new Playback();clock.loop(true);clock.play(0,1);clock.tick(3_250_000_000L,1);assertEquals(.25,clock.time());assertEquals(3.25,clock.absoluteTime());clock.seek(.7);assertEquals(.7,clock.absoluteTime());assertFalse(clock.playing());}
    @Test void historyMultipleAnimationsConflictsAndAllIdentities(){var d=sample();var h=new CommandHistory(d);h.execute("copy",Commands.model(m->ExtendedEdits.duplicateAnimation(m,id(30),id(31),"copy")));var copy=h.state().model().animation(id(31));assertEquals(d.animation(id(30)).discrete().keys().size(),copy.discrete().keys().size());var ids=new HashSet<EntityId>();d.animation(id(30)).discrete().keys().forEach(k->ids.add(k.id()));assertTrue(copy.discrete().keys().stream().noneMatch(k->ids.contains(k.id())));var before=h.state();assertThrows(IllegalArgumentException.class,()->h.execute("collision",Commands.model(m->ExtendedEdits.renameAnimation(m,id(31),"walk"))));assertEquals(before,h.state());assertEquals(1,h.undoCount());h.execute("delete",Commands.model(m->ExtendedEdits.deleteAnimation(m,id(30))));assertEquals(1,h.state().model().animations().size());assertTrue(h.undo());assertTrue(h.undo());assertEquals(d,h.state().model());assertTrue(h.redo());}
    @Test void numericEditsRetainDiscreteAndResources(){var d=sample();var next=AnimationEdits.put(d,id(30),id(1),Channel.TRANSLATE,.25,List.of(3.,4.));assertEquals(d.resources(),next.resources());assertEquals(d.animation(id(30)).discrete(),next.animation(id(30)).discrete());next=AnimationEdits.remove(next,id(30),Set.of(next.animation(id(30)).keys().get(0).id()));assertEquals(d,next);assertEquals(d.resources(),ModelEdits.editBone(d,id(1),b->b.withName("renamed")).resources());}
    @Test void deleteSlotPrunesEveryReferenceAndUndoRestores(){var d=sample();var h=new CommandHistory(d);h.execute("delete",Commands.model(m->ModelEdits.delete(m,id(10))));var next=h.state().model();assertEquals(2,next.slots().size());assertTrue(next.animation(id(30)).discrete().attachments().isEmpty());assertEquals(2,next.animation(id(30)).discrete().drawOrder().get(0).slots().size());assertTrue(next.skins().stream().noneMatch(s->s.attachments().containsKey(id(10))));h.undo();assertEquals(d,h.state().model());}
    @Test void badReferencesAndPermutationsRejected(){var d=sample();assertThrows(IllegalArgumentException.class,()->ExtendedEdits.drawOrder(d,id(30),.4,List.of(id(10),id(10),id(11))));assertThrows(IllegalArgumentException.class,()->ExtendedEdits.drawOrder(d,id(30),.4,List.of(id(10))));assertThrows(IllegalArgumentException.class,()->ExtendedEdits.attachment(d,id(30),id(999),.4,"unknown"));assertThrows(IllegalArgumentException.class,()->ExtendedEdits.createAnimation(d,id(99),"walk"));}
    @Test void missingAttachmentPlaceholderHidesSlotAndSurvivesProjectRoundtrip() throws Exception {
        var original=sample();
        var changed=ExtendedEdits.attachment(original,id(30),id(10),.4,"unknown");
        assertNull(changed.resolvedSlots(id(30),.4,false).get(0).activeAttachmentId());
        assertEquals(id(20),original.resolvedSlots(id(30),.4,false).get(0).activeAttachmentId());
        assertEquals("unknown",changed.animation(id(30)).discrete().attachments().stream()
                .filter(k->k.time()==.4).findFirst().orElseThrow().name());
        var codec=new ProjectCodec();
        assertEquals(changed,codec.decode(codec.encode(changed)));
        assertEquals(original.slots(),changed.slots());
    }
    @Test void schema6StrictRoundTripAndMissingNullDistinction()throws Exception{var d=sample();var codec=new ProjectCodec();var bytes=codec.encode(d);var json=new com.fasterxml.jackson.databind.ObjectMapper();var tree=json.readTree(bytes);assertEquals(6,tree.path("schemaVersion").intValue());assertEquals(d,codec.decode(bytes));var key=(com.fasterxml.jackson.databind.node.ObjectNode)tree.path("animations").get(0).path("discrete").path("attachments").get(1);assertTrue(key.get("name").isNull());key.remove("name");assertThrows(ProjectFormatException.class,()->codec.decode(json.writeValueAsBytes(tree)));key.putNull("name");key.put("unknown",1);assertThrows(ProjectFormatException.class,()->codec.decode(json.writeValueAsBytes(tree)));}
    @Test void atlasTrimGeometryAndRotatedUv()throws Exception{var d=sample();var a=new AtlasRegion(100,80,7,9,20,10,40,30,5,6,true);var atlas=Map.of(id(20),a);d=d.withResources(new Resources(d.resources().skins(),"default",d.resources().events(),atlas));var quad=d.evaluateWorld().regions().get(id(20)).vertices();assertEquals(-7.5,quad.get(0).x(),1e-9);assertEquals(-3,quad.get(0).y(),1e-9);assertEquals(2.5,quad.get(2).x(),1e-9);assertEquals(1.0/3,quad.get(2).y(),1e-9);assertEquals(new Vec2(.07,29./80),a.packedUv(0,0));assertEquals(new Vec2(.17,9./80),a.packedUv(1,1));assertEquals(d,new ProjectCodec().decode(new ProjectCodec().encode(d)));assertThrows(IllegalArgumentException.class,()->new AtlasRegion(10,10,8,8,5,5,5,5,0,0,true));}
    @Test void eventsAndMultipleClipsKeepPhysicsReplayDeterministicAndFilesPure()throws Exception{
        var d=PhysicsReplayTest.fixture();var clip=d.animations().get(0).id();d=ExtendedEdits.eventDefinition(d,new EventDefinition(id(999),"tick",0,0,"","",1,0));d=ExtendedEdits.event(d,clip,new DiscreteTracks.EventKey(EntityId.create(),2,id(999),0,0,"end",1,0));d=ExtendedEdits.duplicateAnimation(d,clip,id(998),"second");assertEquals(2,PhysicsPlayer.duration(d,clip));byte[] saved=new ProjectCodec().encode(d);var baseline=new ArrayList<WorldPose>();
        for(int run=0;run<10;run++){var player=new PhysicsPlayer();for(int tick=0;tick<=120;tick++){var pose=player.seek(d,clip,tick/60.,false);if(run==0)baseline.add(pose);else assertEquals(baseline.get(tick),pose);}var second=player.seek(d,id(998),1,false);assertEquals(baseline.get(60),second);assertEquals(baseline.get(0),player.seek(d,clip,2,true));assertEquals(baseline.get(120),player.seek(d,clip,2,false));assertEquals(baseline.get(3),player.seek(d,clip,.05,false));}
        assertArrayEquals(saved,new ProjectCodec().encode(d));var huge=sample().animation(id(30));assertThrows(IllegalArgumentException.class,()->EventSampler.between(huge,1e100,1e100,true,false));
    }
    @Test void addingSlotsKeepsExistingPermutationsAndUndo(){var d=sample();var h=new CommandHistory(d);h.execute("insert",Commands.model(m->ModelEdits.addSlot(m,new Slot(id(60),"insert",id(1),null),1)));var next=h.state().model();assertEquals(List.of(id(10),id(60),id(11),id(12)),next.slots().stream().map(Slot::id).toList());assertEquals(List.of(id(12),id(60),id(11),id(10)),next.animation(id(30)).discrete().drawOrder().get(0).slots());assertEquals(d.resources(),next.resources());h.undo();assertEquals(d,h.state().model());var appended=ModelEdits.addSlot(d,new Slot(id(61),"last",id(1),null));assertEquals(id(61),appended.animation(id(30)).discrete().drawOrder().get(0).slots().get(3));}
    @Test void recordingAfterLastAnimationDeletionKeepsDuplicateSkinPlaceholders(){var original=sample();var empty=ExtendedEdits.deleteAnimation(original,id(30));var next=ExtendedEdits.ensureAnimation(empty);assertEquals(original.resources(),next.resources());assertEquals(original.attachments(),next.attachments());assertEquals(1,next.animations().size());next=AnimationEdits.put(next,next.animations().get(0).id(),id(1),Channel.TRANSLATE,0,List.of(3.,4.));assertEquals(1,next.animations().get(0).keys().size());assertEquals(id(23),ExtendedEdits.skin(next,"red").resolveAttachment(id(10),"image"));}
}
